package com.urlshortener.model;@jakarta.persistence.Entity@jakarta.persistence.Table(name = "urls")public class Url {@jakarta.persistence.Id@jakarta.persistence.GeneratedValue(strategy = jakarta.persistence.GenerationType.IDENTITY)private Long id;@jakarta.persistence.Column(nullable = false, unique = true, length = 2048)private String longUrl;@jakarta.persistence.Column(nullable = false, unique = true, length = 10)private String shortCode;@jakarta.persistence.Column(nullable = false)private java.time.LocalDateTime createdAt;@jakarta.persistence.Column(nullable = false)private Long clickCount = 0L;public Url() {}public Url(String longUrl, String shortCode) {this.longUrl = longUrl;this.shortCode = shortCode;this.createdAt = java.time.LocalDateTime.now();}public Long getId() {return id;}public void setId(Long id) {this.id = id;}public String getLongUrl() {return longUrl;}public void setLongUrl(String longUrl) {this.longUrl = longUrl;}public String getShortCode() {return shortCode;}public void setShortCode(String shortCode) {this.shortCode = shortCode;}public java.time.LocalDateTime getCreatedAt() {return createdAt;}public void setCreatedAt(java.time.LocalDateTime createdAt) {this.createdAt = createdAt;}public Long getClickCount() {return clickCount;}public void setClickCount(Long clickCount) {this.clickCount = clickCount;}public void incrementClickCount() {this.clickCount++;}}